(c.pre,{children:(0,e.jsx)(c.code,{className:"language-python",children:'from qiskit.circuit.library import FullAdderGate\nfrom qiskit import QuantumCircuit, QuantumRegister, ClassicalRegister\n\nadder = FullAdderGate(3)  # Adder of 3-bit numbers\n\n# Create the number A=2\nreg_a = QuantumRegister(3, "a")\nnumber_a = QuantumCircuit(reg_a)\nnumber_a.initialize(2)  # Number 2; |010>\n\n# Create the number B=3\nreg_b = QuantumRegister(3, "b")\nnumber_b = QuantumCircuit(reg_b)\nnumber_b.initialize(3)  # Number 3; |011>\n\n# Create a circuit to hold everything, including a classical register for\n# the result\nqregs = [\n    QuantumRegister(1, "cin"),\n    QuantumRegister(3, "a"),\n    QuantumRegister(3, "b"),\n    QuantumRegister(1, "cout"),\n]\nreg_result = ClassicalRegister(3)\ncircuit = QuantumCircuit(*qregs, reg_result)\n\n# Compose number initializers with the adder. Adder stores the result to\n# register B, so we\'ll measure those qubits.\ncircuit = (\n    circuit.compose(number_a, qubits=reg_a)\n    .compose(number_b, qubits=reg_b)\n    .compose(adder)\n)\ncircuit.measure(reg_b, reg_result)\ncircuit.draw("mpl")\n'})}),"\n",(0,e.jsx)(c.p,{children:(0,e.jsx)(c.img,{alt:"Output of the previous code cell",src:M(59832).A+"",width:"498",height:"600"})}),"\n",(0,e.jsxs)(c.p,{children:["\u05d3\u05d9\u05de\u05d5\u05d9 \u05d4-Circuit \u05de\u05e8\u05d0\u05d4 \u05e9\u05d4\u05d5\u05d0 \u05de\u05e4\u05d9\u05e7 ",(0,e.jsx)(c.code,{children:"5"})," \u05dc\u05db\u05dc ",(0,e.jsx)(c.code,{children:"1024"})," \u05d4\u05d9\u05e8\u05d5\u05d9\u05d5\u05ea (\u05db\u05dc\u05d5\u05de\u05e8 \u05e0\u05de\u05d3\u05d3 \u05e2\u05dd \u05d4\u05e1\u05ea\u05d1\u05e8\u05d5\u05ea ",(0,e.jsx)(c.code,{children:"1.0"}),")."]}),"\n",(0,e.jsx)(c.pre,{children:(0,e.jsx)(c.code,{className:"language-python",children:'from qiskit.primitives import StatevectorSampler\n\nresult = StatevectorSampler().run([circuit]).result()\n\nprint(f"Count data:\\n {result[0].data.c0.get_int_counts()}")\n'})}),"\n",(0,e.jsx)